package dev.workshopvideo;
import android.content.*;import android.app.WallpaperManager;import org.json.*;import java.io.*;import java.nio.file.*;import java.util.*;
public class WallpaperStoreChecks {
 static int checks;static Context c;static File source;
 static void check(boolean ok,String name){if(!ok)throw new AssertionError(name);checks++;}
 static JSONObject config(String letter,int scope)throws Exception {String name=letter.repeat(32)+".video";Files.write(new File(WallpaperStore.directory(c),name).toPath(),new byte[]{1,2,3});return new JSONObject().put("file",name).put("title",letter).put("which",scope);}
 static String active(int screen){return WallpaperStore.active(c,screen).optString("title");}
 static void fresh(Path root,String name)throws Exception {c=new Context(root.resolve(name).toFile());WallpaperManager.installed=3;source=new File(c.getFilesDir(),"source.video");Files.write(source.toPath(),new byte[]{4,5,6});}
 public static void main(String[] args)throws Exception {
  Path root=Path.of(args[0]);Files.createDirectories(root);fresh(root,"migration");JSONObject a=config("a",3);c.preferences.edit().putString("active",a.toString()).commit();
  JSONObject home=WallpaperStore.stage(c,source,"Home B",false,true,1,new JSONObject().put("pan",true).put("zoom",1.3));
  check(active(1).equals("a")&&active(2).equals("a"),"staging keeps both true legacy screens");
  check(WallpaperStore.engineConfiguration(c,1,false).optString("title").equals("a")&&WallpaperStore.engineConfiguration(c,2,false).optString("title").equals("a"),"pending candidate never enters either running engine");
  check(WallpaperStore.engineConfiguration(c,1,true).optString("title").equals("Home B"),"only preview reads candidate");
  WallpaperStore.activate(c,home);String lockBefore=WallpaperStore.active(c,2).toString();check(active(1).equals("Home B")&&active(2).equals("a"),"home-only update preserves lock");
  JSONObject lock=WallpaperStore.stage(c,source,"Lock C",false,true,2,new JSONObject().put("pan",true).put("zoom",1.7));WallpaperStore.activate(c,lock);
  check(active(1).equals("Home B")&&active(2).equals("Lock C"),"distinct home and lock contents coexist");
  check(WallpaperStore.active(c,1).getJSONObject("effects").getDouble("zoom")==1.3&&WallpaperStore.active(c,2).getJSONObject("effects").getDouble("zoom")==1.7,"scope effects remain independent");
  check(WallpaperStore.active(c,1).optBoolean("pan")&&!WallpaperStore.active(c,2).optBoolean("pan")&&!WallpaperStore.active(c,2).getJSONObject("effects").getBoolean("pan"),"lock configuration cannot page in top-level or nested effects");
  lockBefore=WallpaperStore.active(c,2).toString();JSONObject replacement=WallpaperStore.stage(c,source,"New Home",false,false,1,new JSONObject().put("touch",true));WallpaperStore.activate(c,replacement);
  check(lockBefore.equals(WallpaperStore.active(c,2).toString()),"home replacement preserves complete lock snapshot byte for byte");
  WallpaperStore.cleanup(c);check(WallpaperStore.file(c,WallpaperStore.active(c,1)).isFile()&&WallpaperStore.file(c,WallpaperStore.active(c,2)).isFile(),"cleanup retains independent active files");check(!WallpaperStore.file(c,home).exists(),"unused old home copy no longer held for undo");
  JSONObject pending=WallpaperStore.stage(c,source,"Cancel E",false,false,1);WallpaperStore.cancel(c,pending);check(!WallpaperStore.file(c,pending).exists(),"canceled candidate removed");
  pending=WallpaperStore.stage(c,source,"Pending F",false,false,2);JSONObject newer=WallpaperStore.stage(c,source,"Pending G",false,false,1);WallpaperStore.cancel(c,pending);
  check(WallpaperStore.read(c,"pending").optString("file").equals(newer.optString("file")),"late cancel preserves newer candidate");
  check(active(1).equals("New Home")&&active(2).equals("Lock C"),"new pending leaves active screens unchanged");
  WallpaperManager.installed=0;boolean rejected=false;try{WallpaperStore.activate(c,newer);}catch(IOException expected){rejected=true;}check(rejected&&active(1).equals("New Home")&&active(2).equals("Lock C"),"OS selection required before commit");
  WallpaperManager.installed=2;rejected=false;try{WallpaperStore.activate(c,newer);}catch(IOException expected){rejected=true;}check(rejected&&lockBefore.equals(WallpaperStore.active(c,2).toString()),"wrong selected screen cannot overwrite opposite configuration");
  WallpaperManager.installed=3;File folder=WallpaperStore.directory(c);Set<String> before=new HashSet<>(Arrays.asList(folder.list()));c.preferences.failNext=true;rejected=false;try{WallpaperStore.stage(c,source,"Failed H",false,false,1);}catch(IOException expected){rejected=true;}check(rejected&&new HashSet<>(Arrays.asList(folder.list())).equals(before),"failed stage removes only new file");
  fresh(root,"first-bind");JSONObject first=WallpaperStore.stage(c,source,"First home",false,false,1);check(WallpaperStore.engineConfiguration(c,1,false).length()==0&&WallpaperStore.engineConfiguration(c,2,false).length()==0,"first staging must not bind an uncommitted wallpaper");WallpaperStore.activate(c,first);
  check(active(1).equals("First home")&&WallpaperStore.active(c,2).length()==0,"OS both mask does not seed requested home into lock");
  check(c.preferences.contains("activeLock"),"explicit empty lock snapshot blocks global fallback");
  JSONObject second=WallpaperStore.stage(c,source,"Second lock",false,false,2);check(WallpaperStore.engineConfiguration(c,2,false).length()==0,"new lock candidate cannot leak before commit");WallpaperStore.activate(c,second);WallpaperStore.cleanup(c);
  check(active(1).equals("First home")&&WallpaperStore.file(c,first).isFile(),"first lock commit retains home file");
  fresh(root,"legacy-home-only");a=config("a",1);c.preferences.edit().putString("active",a.toString()).commit();check(active(1).equals("a")&&WallpaperStore.active(c,2).length()==0,"legacy home which is respected before migration");
  WallpaperStore.stage(c,source,"Candidate",false,false,2);check(active(1).equals("a")&&WallpaperStore.active(c,2).length()==0,"legacy home migration never invents lock wallpaper");
  c.preferences.edit().putString("activeLock","{}").putString("active",config("b",3).toString()).commit();check(WallpaperStore.active(c,2).length()==0,"explicit empty lock is stronger than legacy both fallback");WallpaperStore.stage(c,source,"Migrate",false,false,1);check(WallpaperStore.active(c,2).length()==0,"migration does not overwrite explicit empty lock");
  JSONObject old=config("c",3);c.preferences.edit().putString("previous",old.toString()).putString("previousHome",old.toString()).putString("previousLock",old.toString()).putString("previousComponent","legacy").commit();WallpaperStore.stage(c,source,"Clean history",false,false,1);
  check(!c.preferences.contains("previous")&&!c.preferences.contains("previousHome")&&!c.preferences.contains("previousLock")&&!c.preferences.contains("previousComponent"),"removed undo preference keys migrated away");check(!WallpaperStore.file(c,old).exists(),"history files no longer retained");
  fresh(root,"both-scroll");JSONObject both=WallpaperStore.stage(c,source,"Both with paging",false,true,3,new JSONObject().put("pan",true).put("scrollStrength",.9));WallpaperStore.activate(c,both);check(WallpaperStore.active(c,1).optBoolean("pan")&&!WallpaperStore.active(c,2).optBoolean("pan"),"both-screen selection enables paging only on home");
  check(WallpaperStore.matchesActive(c,3,both.optString("file")),"both confirmation requires both active configurations");JSONObject nextHome=WallpaperStore.stage(c,source,"Different home",false,false,1);WallpaperStore.activate(c,nextHome);check(!WallpaperStore.matchesActive(c,3,nextHome.optString("file"))&&WallpaperStore.matchesActive(c,1,nextHome.optString("file")),"home-only content cannot confirm a both-screen request");
  c.preferences.edit().putString("renderedFile1","candidate").commit();check(WallpaperStore.matchesRendered(c,1,"candidate")&&!WallpaperStore.matchesRendered(c,2,"candidate")&&!WallpaperStore.matchesRendered(c,3,"candidate"),"home frame evidence cannot confirm lock or both screens");c.preferences.edit().putString("renderedFile2","candidate").commit();check(WallpaperStore.matchesRendered(c,3,"candidate"),"both frame evidence needed for both-screen running status");
  fresh(root,"video-options");JSONObject options=new JSONObject().put("alignment","free").put("pan",true).put("motionMode","scroll").put("pageMode","manual").put("fallbackPages",5).put("flip",true).put("batteryStatic",false).put("contrast",1.4).put("hue",45);JSONObject video=WallpaperStore.stage(c,source,"Free video",true,true,3,options);WallpaperStore.activate(c,video);JSONObject vh=WallpaperStore.active(c,1).getJSONObject("effects"),vl=WallpaperStore.active(c,2).getJSONObject("effects");check(WallpaperStore.active(c,1).optBoolean("pan")&&vh.optBoolean("pan"),"free video can keep home paging when zoom provides room");check(!WallpaperStore.active(c,2).optBoolean("pan")&&!vl.optBoolean("pan"),"free video never propagates home paging to lock");check(vh.optInt("fallbackPages")==5&&vh.optString("pageMode").equals("manual")&&vh.optBoolean("flip")&&!vh.optBoolean("batteryStatic",true)&&vh.optDouble("contrast")==1.4&&vh.optDouble("hue")==45,"video display and power choices survive durable scope snapshots");
  System.out.println("PASS: "+checks+" production wallpaper-store isolation checks");
 }
}
